def interp(xs, ys, x):
    import bisect
    pts = {}
    for a, b in zip(xs, ys):
        if b is None or b != b:
            continue
        pts.setdefault(a, []).append(b)
    if not pts:
        raise ValueError('no points')
    ks = sorted(pts)
    vs = [sum(pts[k]) / len(pts[k]) for k in ks]
    if x <= ks[0]:
        return vs[0]
    if x >= ks[-1]:
        return vs[-1]
    j = bisect.bisect_right(ks, x)
    x0, x1, y0, y1 = ks[j - 1], ks[j], vs[j - 1], vs[j]
    return y0 + (y1 - y0) * (x - x0) / (x1 - x0)

